<?php
namespace App\Controllers;

use App\Core\{Auth,CSRF,Database,TenantContext,View,Audit,Encryption,HttpException};
use App\Services\{CheckoutService,ProductEvent,MercadoPagoProvider,SubscriptionModuleService};

final class BillingController
{
    public function index():void
    {
        Auth::requireLogin();$t=TenantContext::id();$pdo=Database::connection();$s=$pdo->prepare('SELECT s.*,p.name plan_name,p.monthly_price FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.tenant_id=:t ORDER BY s.id DESC LIMIT 1');$s->execute(['t'=>$t]);$subscription=$s->fetch();$i=$pdo->prepare('SELECT * FROM invoices WHERE tenant_id=:t ORDER BY created_at DESC LIMIT 50');$i->execute(['t'=>$t]);$requests=$pdo->prepare('SELECT br.*,st.protocol,st.status ticket_status,sm.id attachment_id FROM billing_support_requests br JOIN support_tickets st ON st.id=br.ticket_id LEFT JOIN support_messages sm ON sm.id=br.attachment_message_id WHERE br.tenant_id=:t ORDER BY br.id DESC LIMIT 30');$requests->execute(['t'=>$t]);$pix=$pdo->prepare('SELECT public_id,amount,status,expires_at,created_at FROM pix_charges WHERE tenant_id=:t ORDER BY id DESC LIMIT 20');$pix->execute(['t'=>$t]);$modulePricing=(new SubscriptionModuleService())->breakdown($t);View::render('billing/index',['title'=>'Minha assinatura','subscription'=>$subscription,'modulePricing'=>$modulePricing,'invoices'=>$i->fetchAll(),'billingRequests'=>$requests->fetchAll(),'pixCharges'=>$pix->fetchAll(),'pixEnabled'=>(bool)\App\Services\PlatformSetting::get('mercadopago.pix.enabled',true),'pixDiscount'=>(float)\App\Services\PlatformSetting::get('mercadopago.pix.discount_percent',0)]);
    }

    public function plans():void
    {
        Auth::requireLogin();$t=TenantContext::id();$pdo=Database::connection();$s=$pdo->prepare('SELECT s.plan_id,p.monthly_price,p.name FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.tenant_id=:t ORDER BY s.id DESC LIMIT 1');$s->execute(['t'=>$t]);$current=$s->fetch();$min=(float)($current['monthly_price']??0);$q=$pdo->prepare('SELECT * FROM plans WHERE active=1 AND (public_visible=1 OR id=:current) AND monthly_price>=:price ORDER BY monthly_price,sort_order');$q->execute(['price'=>$min,'current'=>(int)($current['plan_id']??0)]);$plans=$q->fetchAll();foreach($plans as &$p){$m=$pdo->prepare('SELECT m.name,m.slug FROM plan_modules pm JOIN modules m ON m.id=pm.module_id WHERE pm.plan_id=:p AND pm.enabled=1 AND m.active=1 ORDER BY m.name');$m->execute(['p'=>$p['id']]);$p['modules']=$m->fetchAll();}View::render('billing/plans',['title'=>'Upgrade de plano','plans'=>$plans,'current'=>$current]);
    }

    public function checkout(string $plan):void
    {
        Auth::requireLogin();$cycle=(string)($_GET['cycle']??'monthly');$t=TenantContext::id();try{$quote=(new CheckoutService())->quote((int)$plan,$cycle,(string)($_GET['coupon']??''));$quote=(new SubscriptionModuleService())->augmentQuote($t,$cycle,$quote);$this->assertUpgrade((int)$plan);}catch(\DomainException $e){HttpException::abort(422,$e->getMessage());}ProductEvent::record('CHECKOUT_STARTED',$t,Auth::user()['id'],['plan_id'=>(int)$plan]);View::render('billing/checkout',['title'=>'Checkout','quote'=>$quote,'gatewayReady'=>$this->gatewayReady()]);
    }

    public function createCheckout(string $plan):void
    {
        Auth::requireLogin();CSRF::enforce();$t=TenantContext::id();$cycle=(string)($_POST['billing_cycle']??'monthly');$this->assertUpgrade((int)$plan);$quote=(new CheckoutService())->quote((int)$plan,$cycle,(string)($_POST['coupon_code']??''));$quote=(new SubscriptionModuleService())->augmentQuote($t,$cycle,$quote);$key=(string)($_POST['idempotency_key']??'');if(!preg_match('/^[a-f0-9]{64}$/',$key))HttpException::abort(422,'Sessão inválida.');$gateway=$this->gateway();if(!$gateway||$gateway['last_test_status']!=='validated'||empty($gateway['active']))HttpException::abort(503,'O gateway de pagamento ainda não foi homologado pelo administrador.');$token=Encryption::decrypt($gateway['access_token_encrypted'])['value']??'';$provider=new MercadoPagoProvider($token);$pdo=Database::connection();$pdo->beginTransaction();try{$existing=$pdo->prepare('SELECT id,status FROM checkout_sessions WHERE tenant_id=:t AND idempotency_key=:k LIMIT 1 FOR UPDATE');$existing->execute(['t'=>$t,'k'=>$key]);if($old=$existing->fetch()){if(in_array($old['status'],['awaiting_payment','paid'],true)){$pdo->commit();header('Location: /billing');exit;}}$public=bin2hex(random_bytes(16));$pdo->prepare("INSERT INTO checkout_sessions(public_id,tenant_id,plan_id,billing_cycle,subtotal,discount,total,base_total,addon_total,coupon_code,status,idempotency_key,expires_at,created_at,updated_at)VALUES(:public,:tenant,:plan,:cycle,:subtotal,:discount,:total,:base_total,:addon_total,:coupon,'awaiting_payment',:key,DATE_ADD(NOW(),INTERVAL 24 HOUR),NOW(),NOW())")->execute(['public'=>$public,'tenant'=>$t,'plan'=>$plan,'cycle'=>$cycle,'subtotal'=>$quote['subtotal'],'discount'=>$quote['discount'],'total'=>$quote['total'],'base_total'=>$quote['base_total'],'addon_total'=>$quote['addon_total'],'coupon'=>$quote['coupon']['code']??null,'key'=>$key]);$checkout=(int)$pdo->lastInsertId();$sub=$pdo->prepare('SELECT * FROM subscriptions WHERE tenant_id=:t ORDER BY id DESC LIMIT 1 FOR UPDATE');$sub->execute(['t'=>$t]);$subscription=$sub->fetch();if(!$subscription)throw new \DomainException('Assinatura atual não encontrada.');$number='INV-'.date('Ym').'-'.strtoupper(substr($public,0,8));$due=$this->billingDue($subscription);$pdo->prepare("INSERT INTO invoices(tenant_id,subscription_id,checkout_session_id,number,amount,status,due_at,created_at,updated_at)VALUES(:tenant,:sub,:checkout,:number,:amount,'pending',:due,NOW(),NOW())")->execute(['tenant'=>$t,'sub'=>$subscription['id'],'checkout'=>$checkout,'number'=>$number,'amount'=>$quote['total'],'due'=>$due]);$invoice=(int)$pdo->lastInsertId();$app=require __DIR__.'/../../config/app.php';$months=['monthly'=>1,'quarterly'=>3,'semiannual'=>6,'annual'=>12][$cycle];$trialDays=$this->remainingTrialDays($subscription);$external=$provider->createSubscription(['reason'=>'Assinatura '.$quote['plan']['name'],'external_reference'=>$public,'payer_email'=>Auth::user()['email'],'back_url'=>rtrim($app['url'],'/').'/billing','amount'=>$quote['total'],'frequency'=>$months,'trial_days'=>$trialDays,'idempotency_key'=>$key]);$reference=(string)$external['reference'];$pdo->prepare("INSERT INTO payments(tenant_id,subscription_id,purpose,reference_id,provider,environment,provider_reference,idempotency_key,amount,status,due_at,created_at,updated_at)VALUES(:tenant,:sub,'subscription',NULL,'mercadopago',:environment,:reference,:key,:amount,'pending',:due,NOW(),NOW())")->execute(['tenant'=>$t,'sub'=>$subscription['id'],'environment'=>$gateway['environment']??'unknown','reference'=>$reference,'key'=>$key,'amount'=>$quote['total'],'due'=>$due]);$pdo->prepare('UPDATE subscriptions SET provider_subscription_id=:ref,updated_at=NOW() WHERE id=:id AND tenant_id=:t')->execute(['ref'=>$reference,'id'=>$subscription['id'],'t'=>$t]);$pdo->commit();Audit::log('checkout.create','invoices',$invoice,null,['plan_id'=>(int)$plan,'cycle'=>$cycle,'total'=>$quote['total'],'provider'=>'mercadopago','sandbox'=>$gateway['environment']==='sandbox']);$init=(string)($external['init_point']??'');if($init!==''&&filter_var($init,FILTER_VALIDATE_URL)){header('Location: '.$init);exit;}}catch(\PDOException $e){if($pdo->inTransaction())$pdo->rollBack();if($e->getCode()==='23000'){header('Location: /billing');exit;}throw $e;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$safe=mb_substr($e->getMessage(),0,350);error_log('[ApPlanner MercadoPago] tenant='.(int)$t.' error='.$safe);Audit::log('checkout.mercadopago_failed','tenants',(int)$t,null,['error'=>$safe]);HttpException::abort(502,'Mercado Pago recusou a assinatura: '.$safe);}header('Location: /billing');exit;
    }

    private function assertUpgrade(int $planId):void
    {
        $t=TenantContext::id();$pdo=Database::connection();$q=$pdo->prepare('SELECT p.monthly_price current_price,s.plan_id FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.tenant_id=:t ORDER BY s.id DESC LIMIT 1');$q->execute(['t'=>$t]);$current=$q->fetch();$p=$pdo->prepare('SELECT monthly_price FROM plans WHERE id=:id AND active=1');$p->execute(['id'=>$planId]);$target=$p->fetchColumn();if($target===false)throw new \DomainException('Plano indisponível.');if($current&&(float)$target<(float)$current['current_price'])throw new \DomainException('Esta tela permite apenas manter o plano atual ou migrar para um plano superior.');
    }
    private function gateway():array|false{return Database::connection()->query("SELECT * FROM payment_gateways WHERE provider='mercadopago' AND active=1 AND last_test_status='validated' ORDER BY (environment='production') DESC,last_tested_at DESC LIMIT 1")->fetch();}
    private function gatewayReady():bool{$g=$this->gateway();return (bool)$g&&!empty($g['active'])&&$g['last_test_status']==='validated';}
    private function remainingTrialDays(array $subscription):int{if(($subscription['status']??'')!=='trial'||empty($subscription['trial_ends_at']))return 0;$seconds=strtotime((string)$subscription['trial_ends_at'])-time();return $seconds>0?(int)ceil($seconds/86400):0;}
    private function billingDue(array $subscription):string{return $this->remainingTrialDays($subscription)>0?(string)$subscription['trial_ends_at']:(new \DateTimeImmutable('+1 day'))->format('Y-m-d H:i:s');}
}
